{
  "operations": [
    {
      "filePath": "Components/Coder/TestBenchmarkGrid.razor",
      "operation": "create",
      "oldText": "",
      "newText": "<RadzenDataGrid Data="@benchmarkResults">
    <Columns>
        <RadzenGridColumn TItem="BenchmarkResult" Field="Model" Title="Model" />
        <RadzenGridColumn TItem="BenchmarkResult" Field="Score" Title="Score" />
        <RadzenGridColumn TItem="BenchmarkResult" Field="ElapsedSeconds" Title="Elapsed Seconds" />
        <RadzenGridColumn TItem="BenchmarkResult" Field="Status" Title="Status" />
    </Columns>
</RadzenDataGrid>

@code {
    private List<BenchmarkResult> benchmarkResults = new List<BenchmarkResult>
    {
        new BenchmarkResult { Model = "Model1", Score = 95, ElapsedSeconds = 2.3, Status = "Passed" },
        new BenchmarkResult { Model = "Model2", Score = 88, ElapsedSeconds = 1.9, Status = "Failed" }
    };

    public class BenchmarkResult
    {
        public string Model { get; set; }
        public int Score { get; set; }
        public double ElapsedSeconds { get; set; }
        public string Status { get; set; }
    }
}
",
      "summary": "Create test benchmark grid component"
    }
  ]
}

{
  "operations": [
    {
      "filePath": "Components/Coder/TestBenchmarkDialog.razor",
      "operation": "create",
      "oldText": "",
      "newText": "<RadzenDialog @bind-Visible="visible" Title="Benchmark Details">
    <p>Benchmark details will be shown here.</p>
    <RadzenButton Text="Close" OnClick="CloseDialog" Style="margin-right: 10px;" />
    <RadzenButton Text="Run Again" OnClick="RunBenchmark" />
</RadzenDialog>

@code {
    [Inject]
    private DialogService DialogService { get; set; }

    private bool visible = true;

    private void CloseDialog()
    {
        visible = false;
        DialogService.CloseDialog(this);
    }

    private void RunBenchmark()
    {
        // Logic to run benchmark
    }
}
",
      "summary": "Create TestBenchmarkDialog component with DialogService injection, benchmark details display, and Close and Run Again buttons"
    }
  ]
}

